public sealed class PlaceOrderService(IOrderRepository orders, ICustomerRepository customers,
                                     AppDbContext db, IOutbox outbox)
{
    public async Task<OrderId> PlaceAsync(PlaceOrderCommand cmd, CancellationToken ct)
    {
        var customer = await customers.GetAsync(cmd.CustomerId, ct);
        var order = customer.PlaceOrder(cmd.Items);   // the aggregate decides
        orders.Add(order);
        await outbox.AddAsync(new OrderPlaced(order.Id), ct);
        await db.SaveChangesAsync(ct);                // state + outbox commit together
        return order.Id;
    }
}

