public sealed class PlaceOrderHandler(AppDbContext db, IOrderRepository orders)
    : IRequestHandler<PlaceOrderCommand, OrderId>
{
    public async Task<OrderId> Handle(PlaceOrderCommand cmd, CancellationToken ct)
    {
        var customer = await db.Customers.FindAsync([cmd.CustomerId], ct);
        var order = customer!.PlaceOrder(cmd.Items);   // the aggregate decides
        orders.Add(order);
        await db.SaveChangesAsync(ct);
        return order.Id;
    }
}
